# Mollusc shells generated by Raup's coiling model (wikibio.zoomorph). A: the model: a generating curve
# (the aperture outline) revolves about the coiling axis; per revolution its size grows by the whorl
# expansion rate W, D is the distance of its inner edge from the axis relative to the outer edge, and T is
# its translation along the axis relative to its distance from it. B: a gastropod (W = 2, D = 0.15,
# T = 2.2; dextral: apex up, aperture on the right): apex, spire, suture, body whorl, aperture.
# C: a planispiral cephalopod shell (T = 0) seen along the axis: involute or evolute depending on W and D.
# D: a bivalve valve (very high W: less than one whorl), with the umbo, ligament and commarginal growth
# lines. E: suture lines of shelled cephalopods, where the septa meet the outer wall (aperture up; saddles
# point towards the aperture, lobes towards the apex), increasingly folded from orthoceratitic
# (nautiloids) through goniatitic (Devonian-Permian) and ceratitic (mainly Triassic) to ammonitic
# (mainly Jurassic-Cretaceous) types.
import numpy as np

import wikibio as bio
from wikibio import zoomorph as zm

P = bio.P
fig, ax = bio.canvas(27, 15.4)

# A: model parameters, in a section through the axis (two successive whorls of the generating curve)
bio.panel(ax, "A", (0.2, 15.2))
ax0 = 1.0
ax.plot([ax0, ax0], [7.9, 14.3], color=P.muted(), lw=1.0, ls=(0, (4, 3)))
bio.label(ax, (ax0, 14.55), "Coiling axis", size="tiny", color=P.muted())
k, W, D, T = 1.9, 2.4, 0.45, 0.75
t = np.linspace(0, 2 * np.pi, 80)
arr = dict(arrowstyle="<->", color=P.ink(), lw=0.7, shrinkA=0, shrinkB=0)
cs = []
for i, r in enumerate((1.0, W)):
    rc, a = r * (1 + D) / 2 * k, r * (1 - D) / 2 * k
    cx, cy = ax0 + rc, 13.4 - T * rc
    ax.fill(cx + a * np.cos(t), cy + a * np.sin(t), facecolor=P.fill(zm.SHELL), edgecolor=P.edge(zm.SHELL), lw=1.0)
    ax.add_patch(bio.core.Circle((cx, cy), 0.05, color=P.ink(), zorder=8))
    cs.append((cx, cy, a))
(c1x, c1y, a1), (c2x, c2y, a2) = cs
ax.annotate("", (ax0 + k, c1y + a1 + 0.25), (ax0, c1y + a1 + 0.25), arrowprops=arr)
bio.label(ax, (ax0 + k / 2, c1y + a1 + 0.5), "r1", size="tiny")
ax.annotate("", (ax0 + W * k, c2y - a2 - 0.3), (ax0, c2y - a2 - 0.3), arrowprops=arr)
bio.label(ax, (ax0 + W * k / 2, c2y - a2 - 0.55), "r2 (outer edge)", size="tiny")
ax.annotate("", (ax0 + D * W * k, c2y), (ax0, c2y), arrowprops=arr)
bio.label(ax, (ax0 + D * W * k / 2, c2y + 0.22), "d", size="tiny")
xs = c2x + a2 + 0.3
ax.plot([c1x, xs], [c1y, c1y], color=P.muted(), lw=0.6, ls=":")
ax.plot([c2x, xs], [c2y, c2y], color=P.muted(), lw=0.6, ls=":")
ax.annotate("", (xs, c2y), (xs, c1y), arrowprops=dict(arrowstyle="->", color=P.ink(), lw=0.7, shrinkA=0, shrinkB=0))
bio.label(ax, (xs + 0.12, (c1y + c2y) / 2), "axial\nshift", size="tiny", ha="left")
yy = 7.5
for text in ("W = r2 / r1 (per revolution)", "D = d / r", "T = axial shift / radial distance"):
    bio.label(ax, (0.6, yy), text, size="tiny", ha="left")
    yy -= 0.4

# B: gastropod with parts
bio.panel(ax, "B", (6.9, 15.2))
g = zm.raup_shell(ax, (10.0, 10.9), 5.8, W=2.0, D=0.15, T=2.2, elev=12)
bio.callout(ax, g["apex"], (12.6, 14.2), "Apex")
bio.callout(ax, g["spire"], (12.6, 12.9), "Spire")
bio.callout(ax, g["suture"], (7.6, 11.9), "Suture")
bio.callout(ax, g["body_whorl"], (7.6, 9.6), "Body whorl")
bio.callout(ax, g["aperture"], (13.1, 8.6), "Aperture")
bio.callout(ax, g["lip"], (13.1, 9.6), "Outer lip")

# C: planispiral cephalopod
bio.panel(ax, "C", (14.0, 15.2))
c = zm.raup_shell(ax, (17.0, 11.2), 5.0, W=2.2, D=0.3, T=0.0, elev=90, azim=200)
bio.callout(ax, c["umbilicus"], (19.9, 14.2), "Umbilicus")
bio.callout(ax, c["aperture"], (19.9, 8.7), "Aperture")
bio.callout(ax, c["body_whorl"], (14.6, 13.6), "Body chamber")
bio.label(ax, (17.0, 8.0), "W = 2.2, D = 0.3, T = 0", size="tiny", color=P.muted())

# D: bivalve valve
bio.panel(ax, "D", (21.3, 15.2))
v = zm.bivalve(ax, (24.2, 11.3), 4.4, ribs=0, growth=8)
bio.callout(ax, v["umbo"], (22.3, 12.8), "Umbo")
bio.callout(ax, v["ligament"], (26.6, 14.0), "Ligament")
bio.callout(ax, v["growth_line"], (26.6, 9.0), "Growth lines")
bio.label(ax, (v["anterior"][0] - 0.05, v["anterior"][1]), "Ant.", size="tiny", ha="right", color=P.muted())
bio.label(ax, (24.2, 8.6), "Left valve, outside; ventral margin below", size="tiny", color=P.muted())

# E: suture types
bio.panel(ax, "E", (0.2, 6.4))
EX = [("orthoceratitic", "Orthoceratitic", "nautiloids"), ("goniatitic", "Goniatitic", "goniatites, Devonian-Permian"),
      ("ceratitic", "Ceratitic", "ceratites, Triassic"), ("ammonitic", "Ammonitic", "ammonites, Jurassic-Cretaceous")]
for i, (kind, title, ex) in enumerate(EX):
    x0 = 0.9 + i * 6.6
    s = zm.suture(ax, (x0, 3.3), 5.4, kind, lobes=2, amplitude=1.05)
    bio.label(ax, (x0 + 2.7, 5.85), title, size="normal", bold=True)
    bio.label(ax, (x0 + 2.7, 5.35), ex, size="tiny", color=P.muted())
    if i == 1:
        bio.callout(ax, s["saddle"], (x0 + 3.6, 4.9), "Saddle", size="tiny")
        bio.callout(ax, s["lobe"], (x0 + 2.0, 1.5), "Lobe", size="tiny")
bio.arrow(ax, (26.4, 2.4), (26.4, 4.6), kind="process", head=0.2, lw=1.0)
bio.label(ax, (26.4, 2.1), "towards\naperture", size="tiny", va="top")
